+			if errors.As(err, &exit) && exit.ExitCode() == 1 {
+				continue
+			}
+			if ctx.Err() != nil {
+				return ctx.Err()
+			}
+			return internal("cannot inspect file-first Git command configuration")
+		}
+		if len(keys) > 0 {
+			return safety("file-first external Git filters or fsmonitor are unsupported")
+		}
+	}
