+		return internal("cannot inspect file-first index modes")
+	}
+	for _, entry := range splitNUL(entries) {
+		if strings.HasPrefix(entry, "160000 ") {
+			return safety("file-first repositories with gitlinks are unsupported")
+		}
+	}
+	return nil
+}
