+func fileFirstWithinLineBudget(content []byte) bool {
+	lines := bytes.Count(content, []byte{'\n'})
+	if len(content) > 0 && content[len(content)-1] != '\n' {
+		lines++
+	}
+	return lines <= fileFirstMaxLines
+}
