+	content, err := io.ReadAll(io.LimitReader(file, fileFirstMaxBytes+1))
+	if err != nil {
+		return nil, err
+	}
+	if len(content) > fileFirstMaxBytes {
+		return nil, safety("file-first selected byte budget exceeded")
+	}
+	return content, nil
+}
